```python
def count_vowels(s):
    vowels = 'aeiouAEIOU'
    count = 0
    i = 0

    def vowel_count(k):
        global count
        nonlocal i
        if k > len(s):
            return 0
        if not s[k].isdigit() and not s[k].isalpha():
            return vowel_count(k+1)
        if s[k] in vowels:
            count += 1
        if i > 3:
            return 0
        i += 1
        return vowel_count(k+1)

    return vowel_count(0)
```
